import { chromium } from 'playwright'

const base = 'http://127.0.0.1:8092'
const url = `${base}/#/UnifiedLogin?portal=rental-opening&detail=rental-enterprise`
const out = process.argv[2] || 'D:/repository/门户/_verify_after.png'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } })
await page.goto(url, { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.rental-enterprise-grid', { timeout: 20000 })
await page.waitForTimeout(800)

const info = await page.evaluate(() => {
  const dlg = document.querySelector('.rental-detail-dialog')
  const grid = document.querySelector('.rental-enterprise-grid')
  const pairs = [...document.querySelectorAll('.rental-enterprise-grid .rental-field-pair')]
  const scopePair = pairs.find((p) => p.querySelector('.rental-field-label')?.textContent.trim() === '经营范围')
  const scopeVal = scopePair?.querySelector('.rental-field-value')
  const cs = scopeVal ? getComputedStyle(scopeVal) : null
  return {
    dialogWidth: dlg?.getBoundingClientRect().width,
    gridWidth: grid?.getBoundingClientRect().width,
    scopeWhiteSpace: cs?.whiteSpace,
    scopeOverflowWrap: cs?.overflowWrap,
    scopeHeight: scopeVal?.getBoundingClientRect().height,
    scopeLineHeight: cs?.lineHeight,
    scopeLines: scopeVal ? Math.round(scopeVal.getBoundingClientRect().height / parseFloat(cs.lineHeight)) : null,
    dialogHeight: dlg?.getBoundingClientRect().height,
    scopeText: scopeVal?.textContent.trim().slice(0, 40)
  }
})
console.log(JSON.stringify(info, null, 2))
await page.screenshot({ path: out, fullPage: false })
await browser.close()

import { chromium } from 'playwright'

const base = 'http://127.0.0.1:8092'
const url = `${base}/#/UnifiedLogin?portal=rental-opening&detail=rental-enterprise`
const out = process.argv[2] || 'D:/repository/门户/_verify_long.png'

const longText = '授权范围内的资产经营管理；从事进出口经营（范围按外经贸部外经审函字第266号规定）；经营国内商业、物资供销业（国家规定的专营、专项审批商品除外）；提供生产及生活服务；开展技术开发、技术转让、技术服务；承接机械成套项目、房地产开发业务；为进出口企业提供服务。（依法须经批准的项目，经相关部门批准后方可开展经营活动）'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } })
await page.goto(url, { waitUntil: 'domcontentloaded' })
await page.waitForSelector('.rental-enterprise-grid', { timeout: 20000 })
await page.waitForTimeout(500)

const info = await page.evaluate((txt) => {
  const pairs = [...document.querySelectorAll('.rental-enterprise-grid .rental-field-pair')]
  const scopePair = pairs.find((p) => p.querySelector('.rental-field-label')?.textContent.trim() === '经营范围')
  const scopeVal = scopePair.querySelector('.rental-field-value')
  scopeVal.textContent = txt
  const dlg = document.querySelector('.rental-detail-dialog')
  const cs = getComputedStyle(scopeVal)
  const rect = scopeVal.getBoundingClientRect()
  const lh = parseFloat(cs.lineHeight)
  return {
    dialogWidth: dlg.getBoundingClientRect().width,
    dialogMaxWidth: getComputedStyle(dlg).maxWidth,
    scopeValueWidth: rect.width,
    scopeValueRight: rect.right,
    dialogRight: dlg.getBoundingClientRect().right,
    scopeOverflow: scopeVal.scrollWidth > scopeVal.clientWidth,
    scopeLines: Math.round(rect.height / lh),
    scopeHeight: rect.height,
    dialogHeight: dlg.getBoundingClientRect().height
  }
}, longText)
console.log(JSON.stringify(info, null, 2))
await page.screenshot({ path: out, fullPage: false })
await browser.close()

